    fn exit_enum_constants(&mut self, _ctx: &EnumConstantsContext) -> Result<(), E> { Ok(()) }
    fn enter_enum_constant(&mut self, _ctx: &EnumConstantContext) -> Result<(), E> { Ok(()) }
    fn exit_enum_constant(&mut self, _ctx: &EnumConstantContext) -> Result<(), E> { Ok(()) }
