#[allow(dead_code)]
pub struct JavaValidatedTreeWalker;

#[allow(dead_code)]
impl JavaValidatedTreeWalker {
    pub fn walk<E, T: JavaValidatedListener<E>>(
        listener: &mut T,
        tree: ValidatedRuleNode<'_>,
    ) -> Result<(), E> {
        Self::__walk(listener, tree.node(), None)
    }

    pub fn walk_with_invocation_states<E, T: JavaValidatedListener<E>>(
        listener: &mut T,
        tree: ValidatedRuleNode<'_>,
        parent_invocation_states: Vec<isize>,
    ) -> Result<(), E> {
        Self::__walk(listener, tree.node(), Some(parent_invocation_states))
    }

    fn __walk<E, T: JavaValidatedListener<E>>(
        listener: &mut T,
        tree: antlr4_runtime::Node<'_>,
        invocation_states: Option<Vec<isize>>,
    ) -> Result<(), E> {
        let mut callbacks = __JavaValidatedTreeWalkerCallbacks(listener);
        antlr4_runtime::generated::walk_generated(tree, invocation_states, &mut callbacks)
    }
}

pub type ValidatedParseTreeWalker = JavaValidatedTreeWalker;



